// Search the Vapi webhook payload for the full transcript across possible locations
const results = [];

for (const item of $input.all()) {
  const root = item.json || {};
  const body = root.body || root;
  const msg = body.message || body;
  const call = msg.call || body.call || {};
  const customer = msg.customer || body.customer || call.customer || {};

  // Try direct transcript fields in several known Vapi locations
  let transcript =
    msg.transcript ||
    (msg.artifact && msg.artifact.transcript) ||
    body.transcript ||
    (body.artifact && body.artifact.transcript) ||
    (call && call.transcript) ||
    '';

  // Fallback: reconstruct transcript from a messages array
  if (!transcript) {
    const msgs =
      (msg.artifact && msg.artifact.messages) ||
      msg.messages ||
      (body.artifact && body.artifact.messages) ||
      body.messages ||
      [];
    if (Array.isArray(msgs) && msgs.length) {
      transcript = msgs
        .filter((m) => m && (m.role || m.message || m.content))
        .map((m) => `${m.role || 'unknown'}: ${m.message || m.content || ''}`)
        .join('\n');
    }
  }

  transcript = (transcript == null ? '' : String(transcript)).trim();

  const call_id = call.id || msg.callId || body.call_id || body.callId || '';
  const assistant_id =
    msg.assistantId ||
    (msg.assistant && msg.assistant.id) ||
    call.assistantId ||
    body.assistant_id ||
    '';
  const customer_number =
    customer.number || body.customer_number || body.customerNumber || '';
  const duration =
    msg.durationSeconds ||
    msg.durationMinutes ||
    msg.duration ||
    body.duration ||
    call.duration ||
    '';

  results.push({
    json: {
      call_id: call_id || '',
      assistant_id: assistant_id || '',
      customer_number: customer_number || '',
      duration: duration === 0 ? 0 : (duration || ''),
      transcript: transcript || '',
    },
  });
}

return results;

