// Parse response.choices[0].message.content into structured JSON (safely)

const results = [];
const inputs = $input.all();
const extracted = $('Extract Transcript').all();

const toStr = (v) => {
  if (Array.isArray(v)) return v.map((x) => String(x)).join(', ');
  if (v == null) return '';
  if (typeof v === 'object') return JSON.stringify(v);
  return String(v);
};

const toNum = (v) => {
  const n = parseFloat(v);
  return Number.isFinite(n) ? n : 0;
};

for (let i = 0; i < inputs.length; i++) {

  const item = inputs[i];

  const src = extracted[i]
    ? extracted[i].json
    : (extracted[0] ? extracted[0].json : {});

  let raw =
    item.json?.choices?.[0]?.message?.content ||
    item.json?.body?.choices?.[0]?.message?.content ||
    item.json?.message?.content ||
    '';

  let parsed = {};

  if (raw && typeof raw === 'object') {
    parsed = raw;
  } else if (raw) {

    try {
      parsed = JSON.parse(raw);

    } catch (e) {

      try {

        const match = String(raw).match(/\{[\s\S]*\}/);

        parsed = match
          ? JSON.parse(match[0])
          : {};

      } catch (e2) {
        parsed = {};
      }

    }

  }

  results.push({
    json: {

      // Data from Extract Transcript node
      call_id: src.call_id || '',
      assistant_id: src.assistant_id || '',
      customer_number: src.customer_number || '',
      duration: src.duration || '',
      transcript: src.transcript || '',

      // Evaluation Scores
      overall_score: toNum(parsed.overall_score),
      rapport_score: toNum(parsed.rapport_score),
      discovery_score: toNum(parsed.discovery_score),
      qualification_score: toNum(parsed.qualification_score),
      value_score: toNum(parsed.value_score),
      objection_score: toNum(parsed.objection_score),
      closing_score: toNum(parsed.closing_score),

      // Evaluation Insights
      strengths: toStr(parsed.strengths),
      weaknesses: toStr(parsed.weaknesses),
      missed_opportunities: toStr(parsed.missed_opportunities),
      coaching_recommendations: toStr(parsed.coaching_recommendations),
      summary: parsed.summary || ''

    }
  });

}

return results;
